 const source=suggestions[0]?.source_url||'';
 return `<fieldset class="performer-picker"><legend>Which artists did you see?</legend><p class="muted">${note}${source?` <a class="source-link" href="${esc(source)}" target="_blank" rel="noopener">Source</a>`:''}</p><div class="performer-options">${options}</div><div class="add-performer"><label>Add an opener<input type="text" maxlength="160" list="log-artists" placeholder="Artist name" data-new-performer></label><button type="button" class="secondary" data-add-performer>＋ Add artist</button></div></fieldset>`;
